DROP TABLE IF EXISTS `Customer`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Customer` (
  `Id` int NOT NULL AUTO_INCREMENT,
  `Username` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `Email` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `EmailToRevalidate` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `FirstName` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `LastName` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `Gender` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `Company` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `StreetAddress` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `StreetAddress2` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `ZipPostalCode` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `City` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `County` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `Phone` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `Fax` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `VatNumber` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `TimeZoneId` varchar(1000) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `CustomCustomerAttributesXML` longtext,
  `DateOfBirth` datetime DEFAULT NULL,
  `SystemName` varchar(400) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `LastIpAddress` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL,
  `CurrencyId` int DEFAULT NULL,
  `LanguageId` int DEFAULT NULL,
  `BillingAddress_Id` int DEFAULT NULL,
  `ShippingAddress_Id` int DEFAULT NULL,
  `CustomerGuid` char(36) NOT NULL,
  `CountryId` int NOT NULL,
  `StateProvinceId` int NOT NULL,
  `VatNumberStatusId` int NOT NULL,
  `TaxDisplayTypeId` int DEFAULT NULL,
  `AdminComment` longtext,
  `IsTaxExempt` tinyint(1) NOT NULL,
  `AffiliateId` int NOT NULL,
  `VendorId` int NOT NULL,
  `HasShoppingCartItems` tinyint(1) NOT NULL,
  `RequireReLogin` tinyint(1) NOT NULL,
  `FailedLoginAttempts` int NOT NULL,
  `CannotLoginUntilDateUtc` datetime(6) DEFAULT NULL,
  `Active` tinyint(1) NOT NULL,
  `Deleted` tinyint(1) NOT NULL,
  `IsSystemAccount` tinyint(1) NOT NULL,
  `CreatedOnUtc` datetime(6) NOT NULL,
  `LastLoginDateUtc` datetime(6) DEFAULT NULL,
  `LastActivityDateUtc` datetime(6) NOT NULL,
  `RegisteredInStoreId` int NOT NULL,
  `MustChangePassword` tinyint(1) NOT NULL,
  PRIMARY KEY (`Id`),
  KEY `IX_4E438EF87245E2BD822476ECB990EC1C725A4944` (`CurrencyId`),
  KEY `IX_6FEA75096199DD814FCDC8D621CBF17ED144E3C5` (`LanguageId`),
  KEY `IX_79820CBB6A38BC446E7FC52E7582A458F3A2AC75` (`BillingAddress_Id`),
  KEY `IX_5FD07AEA757DD98D3E04CA86906517868F44A287` (`ShippingAddress_Id`),
  KEY `IX_Customer_Username` (`Username`),
  KEY `IX_Customer_SystemName` (`SystemName`),
  KEY `IX_Customer_Email` (`Email`),
  KEY `IX_Customer_CustomerGuid` (`CustomerGuid`),
  KEY `IX_Customer_CreatedOnUtc` (`CreatedOnUtc` DESC),
  KEY `IX_Customer_Deleted` (`Deleted`),
  CONSTRAINT `FK_0A43673E2B826E9249E45A887B3B3C8A6D4D116C` FOREIGN KEY (`CurrencyId`) REFERENCES `Currency` (`Id`) ON DELETE SET NULL,
  CONSTRAINT `FK_4F620FCCDCB6197FB2B540B35EEE46515DE307E3` FOREIGN KEY (`ShippingAddress_Id`) REFERENCES `Address` (`Id`),
  CONSTRAINT `FK_572D629F64F2591019291A15D1191B6419D3D7B4` FOREIGN KEY (`BillingAddress_Id`) REFERENCES `Address` (`Id`),
  CONSTRAINT `FK_8F9FD2E58251B90AD8E5B3B0C335FF48F970F8F1` FOREIGN KEY (`LanguageId`) REFERENCES `Language` (`Id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=372 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
