INSERT INTO `MessageTemplate` VALUES (1,'Blog.BlogComment',NULL,'%Store.Name%. New blog comment.',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nA new blog comment has been created for blog post \"%BlogComment.BlogPostTitle%\".\n</p>\n',1,NULL,0,0,0,0),(2,'Customer.BackInStock',NULL,'%Store.Name%. Back in stock notification',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nHello %Customer.FullName%,\n<br />\nProduct <a target=\"_blank\" href=\"%BackInStockSubscription.ProductUrl%\">%BackInStockSubscription.ProductName%</a> is in stock.\n</p>\n',1,NULL,0,0,0,0),(3,'Customer.EmailValidationMessage',NULL,'%Store.Name%. Email validation',1,'<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nTo activate your account <a href=\"%Customer.AccountActivationURL%\">click here</a>.\n<br />\n<br />\n%Store.Name%\n',1,NULL,0,0,0,0),(4,'Customer.EmailRevalidationMessage',NULL,'%Store.Name%. Email validation',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nHello %Customer.FullName%!\n<br />\nTo validate your new email address <a href=\"%Customer.EmailRevalidationURL%\">click here</a>.\n<br />\n<br />\n%Store.Name%\n</p>\n',1,NULL,0,0,0,0),(5,'Customer.NewPM',NULL,'%Store.Name%. You have received a new private message',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nYou have received a new private message.\n</p>\n',1,NULL,0,0,0,0),(6,'Customer.PasswordRecovery',NULL,'%Store.Name%. Password recovery',1,'<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nTo change your password <a href=\"%Customer.PasswordRecoveryURL%\">click here</a>.\n<br />\n<br />\n%Store.Name%\n',1,NULL,0,0,0,0),(7,'Customer.WelcomeMessage',NULL,'Welcome to %Store.Name%',1,'We welcome you to <a href=\"%Store.URL%\"> %Store.Name%</a>.\n<br />\n<br />\nYou can now take part in the various services we have to offer you. Some of these services include:\n<br />\n<br />\nPermanent Cart - Any products added to your online cart remain there until you remove them, or check them out.\n<br />\nAddress Book - We can now deliver your products to another address other than yours! This is perfect to send birthday gifts direct to the birthday-person themselves.\n<br />\nOrder History - View your history of purchases that you have made with us.\n<br />\nProducts Reviews - Share your opinions on products with our other customers.\n<br />\n<br />\nFor help with any of our online services, please email the store-owner: <a href=\"mailto:%Store.Email%\">%Store.Email%</a>.\n<br />\n<br />\nNote: This email address was provided on our registration page. If you own the email and did not register on our site, please send an email to <a href=\"mailto:%Store.Email%\">%Store.Email%</a>.\n',1,NULL,0,0,0,0),(8,'Forums.NewForumPost',NULL,'%Store.Name%. New Post Notification.',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nA new post has been created in the topic <a href=\"%Forums.TopicURL%\">\"%Forums.TopicName%\"</a> at <a href=\"%Forums.ForumURL%\">\"%Forums.ForumName%\"</a> forum.\n<br />\n<br />\nClick <a href=\"%Forums.TopicURL%\">here</a> for more info.\n<br />\n<br />\nPost author: %Forums.PostAuthor%\n<br />\nPost body: %Forums.PostBody%\n</p>\n',1,NULL,0,0,0,0),(9,'Forums.NewForumTopic',NULL,'%Store.Name%. New Topic Notification.',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nA new topic <a href=\"%Forums.TopicURL%\">\"%Forums.TopicName%\"</a> has been created at <a href=\"%Forums.ForumURL%\">\"%Forums.ForumName%\"</a> forum.\n<br />\n<br />\nClick <a href=\"%Forums.TopicURL%\">here</a> for more info.\n</p>\n',1,NULL,0,0,0,0),(10,'GiftCard.Notification',NULL,'%GiftCard.SenderName% has sent you a gift card for %Store.Name%',1,'<p>\nYou have received a gift card for %Store.Name%\n</p>\n<p>\nDear %GiftCard.RecipientName%,\n<br />\n<br />\n%GiftCard.SenderName% (%GiftCard.SenderEmail%) has sent you a %GiftCard.Amount% gift card for <a href=\"%Store.URL%\"> %Store.Name%</a>\n</p>\n<p>\nYour gift card code is %GiftCard.CouponCode%\n</p>\n<p>\n%GiftCard.Message%\n</p>\n',1,NULL,0,0,0,0),(11,'NewCustomer.Notification',NULL,'%Store.Name%. New customer registration',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nA new customer registered with your store. Below are the customer\'s details:\n<br />\nFull name: %Customer.FullName%\n<br />\nEmail: %Customer.Email%\n</p>\n',1,NULL,0,0,0,0),(12,'NewReturnRequest.StoreOwnerNotification',NULL,'%Store.Name%. New return request.',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\n%Customer.FullName% has just submitted a new return request. Details are below:\n<br />\nRequest ID: %ReturnRequest.CustomNumber%\n<br />\nProduct: %ReturnRequest.Product.Quantity% x Product: %ReturnRequest.Product.Name%\n<br />\nReason for return: %ReturnRequest.Reason%\n<br />\nRequested action: %ReturnRequest.RequestedAction%\n<br />\nCustomer comments:\n<br />\n%ReturnRequest.CustomerComment%\n</p>\n',1,NULL,0,0,0,0),(13,'Customer.Gdpr.DeleteRequest',NULL,'%Store.Name%. New request to delete customer (GDPR)',1,'%Customer.Email% has requested account deletion. You can consider this in the admin area.',1,NULL,0,0,0,0),(14,'NewReturnRequest.CustomerNotification',NULL,'%Store.Name%. New return request.',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nHello %Customer.FullName%!\n<br />\nYou have just submitted a new return request. Details are below:\n<br />\nRequest ID: %ReturnRequest.CustomNumber%\n<br />\nProduct: %ReturnRequest.Product.Quantity% x Product: %ReturnRequest.Product.Name%\n<br />\nReason for return: %ReturnRequest.Reason%\n<br />\nRequested action: %ReturnRequest.RequestedAction%\n<br />\nCustomer comments:\n<br />\n%ReturnRequest.CustomerComment%\n</p>\n',1,NULL,0,0,0,0),(15,'News.NewsComment',NULL,'%Store.Name%. New news comment.',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nA new news comment has been created for news \"%NewsComment.NewsTitle%\".\n</p>\n',1,NULL,0,0,0,0),(16,'NewsLetterSubscription.ActivationMessage',NULL,'%Store.Name%. Subscription activation message.',1,'<p>\n<a href=\"%NewsLetterSubscription.ActivationUrl%\">Click here to confirm your subscription to our list.</a>\n</p>\n<p>\nIf you received this email by mistake, simply delete it.\n</p>\n',1,NULL,0,0,0,0),(17,'NewsLetterSubscription.DeactivationMessage',NULL,'%Store.Name%. Subscription deactivation message.',1,'<p>\n<a href=\"%NewsLetterSubscription.DeactivationUrl%\">Click here to unsubscribe from our newsletter.</a>\n</p>\n<p>\nIf you received this email by mistake, simply delete it.\n</p>\n',1,NULL,0,0,0,0),(18,'NewVATSubmitted.StoreOwnerNotification',NULL,'%Store.Name%. New VAT number is submitted.',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\n%Customer.FullName% (%Customer.Email%) has just submitted a new VAT number. Details are below:\n<br />\nVAT number: %Customer.VatNumber%\n<br />\nVAT number status: %Customer.VatNumberStatus%\n<br />\nReceived name: %VatValidationResult.Name%\n<br />\nReceived address: %VatValidationResult.Address%\n</p>\n',1,NULL,0,0,0,0),(19,'OrderCancelled.CustomerNotification',NULL,'%Store.Name%. Your order cancelled',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nHello %Order.CustomerFullName%,\n<br />\nYour order has been cancelled. Below is the summary of the order.\n<br />\n<br />\nOrder Number: %Order.OrderNumber%\n<br />\nOrder Details: <a target=\"_blank\" href=\"%Order.OrderURLForCustomer%\">%Order.OrderURLForCustomer%</a>\n<br />\nDate Ordered: %Order.CreatedOn%\n<br />\n<br />\n<br />\n<br />\nBilling Address\n<br />\n%Order.BillingFirstName% %Order.BillingLastName%\n<br />\n%Order.BillingAddress1%\n<br />\n%Order.BillingAddress2%\n<br />\n%Order.BillingCity% %Order.BillingZipPostalCode%\n<br />\n%Order.BillingStateProvince% %Order.BillingCountry%\n<br />\n<br />\n<br />\n<br />\n%if (%Order.Shippable%) Shipping Address\n<br />\n%Order.ShippingFirstName% %Order.ShippingLastName%\n<br />\n%Order.ShippingAddress1%\n<br />\n%Order.ShippingAddress2%\n<br />\n%Order.ShippingCity% %Order.ShippingZipPostalCode%\n<br />\n%Order.ShippingStateProvince% %Order.ShippingCountry%\n<br />\n<br />\nShipping Method: %Order.ShippingMethod%\n<br />\n<br />\n endif% %Order.Product(s)%\n</p>\n',1,NULL,0,0,0,0),(20,'OrderCancelled.StoreOwnerNotification',NULL,'%Store.Name%. Order #%Order.OrderNumber% cancelled',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nOrder #%Order.OrderNumber% has been cancelled by customer.\n<br />\nCustomer: %Order.CustomerFullName%,\n<br />\n<br />\n<br />\nOrder Number: %Order.OrderNumber%\n<br />\nDate Ordered: %Order.CreatedOn%\n<br />\n<br />\n%Order.Product(s)%\n</p>\n',1,NULL,0,0,0,0),(21,'OrderCancelled.VendorNotification',NULL,'%Store.Name%. Order #%Order.OrderNumber% cancelled',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nOrder #%Order.OrderNumber% has been cancelled.\n<br />\nCustomer: %Order.CustomerFullName%,\n<br />\n<br />\n<br />\nOrder Number: %Order.OrderNumber%\n<br />\nDate Ordered: %Order.CreatedOn%\n<br />\n<br />\n%Order.Product(s)%\n</p>\n',1,NULL,0,0,0,0),(22,'OrderProcessing.CustomerNotification',NULL,'%Store.Name%. Your order is processing',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nHello %Order.CustomerFullName%,\n<br />\nYour order is processing. Below is the summary of the order.\n<br />\n<br />\nOrder Number: %Order.OrderNumber%\n<br />\nOrder Details: <a target=\"_blank\" href=\"%Order.OrderURLForCustomer%\">%Order.OrderURLForCustomer%</a>\n<br />\nDate Ordered: %Order.CreatedOn%\n<br />\n<br />\n<br />\n<br />\nBilling Address\n<br />\n%Order.BillingFirstName% %Order.BillingLastName%\n<br />\n%Order.BillingAddress1%\n<br />\n%Order.BillingAddress2%\n<br />\n%Order.BillingCity% %Order.BillingZipPostalCode%\n<br />\n%Order.BillingStateProvince% %Order.BillingCountry%\n<br />\n<br />\n<br />\n<br />\n%if (%Order.Shippable%) Shipping Address\n<br />\n%Order.ShippingFirstName% %Order.ShippingLastName%\n<br />\n%Order.ShippingAddress1%\n<br />\n%Order.ShippingAddress2%\n<br />\n%Order.ShippingCity% %Order.ShippingZipPostalCode%\n<br />\n%Order.ShippingStateProvince% %Order.ShippingCountry%\n<br />\n<br />\nShipping Method: %Order.ShippingMethod%\n<br />\n<br />\n endif% %Order.Product(s)%\n</p>\n',0,NULL,0,0,0,0),(23,'OrderCompleted.CustomerNotification',NULL,'%Store.Name%. Your order completed',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nHello %Order.CustomerFullName%,\n<br />\nYour order has been completed. Below is the summary of the order.\n<br />\n<br />\nOrder Number: %Order.OrderNumber%\n<br />\nOrder Details: <a target=\"_blank\" href=\"%Order.OrderURLForCustomer%\">%Order.OrderURLForCustomer%</a>\n<br />\nDate Ordered: %Order.CreatedOn%\n<br />\n<br />\n<br />\n<br />\nBilling Address\n<br />\n%Order.BillingFirstName% %Order.BillingLastName%\n<br />\n%Order.BillingAddress1%\n<br />\n%Order.BillingAddress2%\n<br />\n%Order.BillingCity% %Order.BillingZipPostalCode%\n<br />\n%Order.BillingStateProvince% %Order.BillingCountry%\n<br />\n<br />\n<br />\n<br />\n%if (%Order.Shippable%) Shipping Address\n<br />\n%Order.ShippingFirstName% %Order.ShippingLastName%\n<br />\n%Order.ShippingAddress1%\n<br />\n%Order.ShippingAddress2%\n<br />\n%Order.ShippingCity% %Order.ShippingZipPostalCode%\n<br />\n%Order.ShippingStateProvince% %Order.ShippingCountry%\n<br />\n<br />\nShipping Method: %Order.ShippingMethod%\n<br />\n<br />\n endif% %Order.Product(s)%\n</p>\n',1,NULL,0,0,0,0),(24,'OrderCompleted.StoreOwnerNotification',NULL,'%Store.Name%. Order #%Order.OrderNumber% completed',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\n%Order.CustomerFullName% has just completed an order. Below is the summary of the order.\n<br />\n<br />\nOrder Number: %Order.OrderNumber%\n<br />\nDate Ordered: %Order.CreatedOn%\n<br />\n<br />\n<br />\n<br />\nBilling Address\n<br />\n%Order.BillingFirstName% %Order.BillingLastName%\n<br />\n%Order.BillingAddress1%\n<br />\n%Order.BillingAddress2%\n<br />\n%Order.BillingCity% %Order.BillingZipPostalCode%\n<br />\n%Order.BillingStateProvince% %Order.BillingCountry%\n<br />\n<br />\n<br />\n<br />\n%if (%Order.Shippable%) Shipping Address\n<br />\n%Order.ShippingFirstName% %Order.ShippingLastName%\n<br />\n%Order.ShippingAddress1%\n<br />\n%Order.ShippingAddress2%\n<br />\n%Order.ShippingCity% %Order.ShippingZipPostalCode%\n<br />\n%Order.ShippingStateProvince% %Order.ShippingCountry%\n<br />\n<br />\nShipping Method: %Order.ShippingMethod%\n<br />\n<br />\n endif% %Order.Product(s)%\n</p>\n',0,NULL,0,0,0,0),(25,'ShipmentDelivered.CustomerNotification',NULL,'Your order from %Store.Name% has been %if (!%Order.IsCompletelyDelivered%) partially endif%delivered.',1,'<p>\n<a href=\"%Store.URL%\"> %Store.Name%</a>\n<br />\n<br />\nHello %Order.CustomerFullName%,\n<br />\nGood news! Your order has been %if (!%Order.IsCompletelyDelivered%) partially endif%delivered.\n<br />\nOrder Number: %Order.OrderNumber%\n<br />\nOrder Details: <a href=\"%Order.OrderURLForCustomer%\" target=\"_blank\">%Order.OrderURLForCustomer%</a>\n<br />\nDate Ordered: %Order.CreatedOn%\n<br />\n<br />\n<br />\n<br />\nBilling Address\n<br />\n%Order.BillingFirstName% %Order.BillingLastName%\n<br />\n%Order.BillingAddress1%\n<br />\n%Order.BillingAddress2%\n<br />\n%Order.BillingCity% %Order.BillingZipPostalCode%\n<br />\n%Order.BillingStateProvince% %Order.BillingCountry%\n<br />\n<br />\n<br />\n<br />\n%if (%Order.Shippable%) Shipping Address\n<br />\n%Order.ShippingFirstName% %Order.ShippingLastName%\n<br />\n%Order.ShippingAddress1%\n<br />\n%Order.ShippingAddress2%\n<br />\n%Order.ShippingAddress2%\n<br />\n%Order.ShippingCity% %Order.ShippingZipPostalCode%\n<br />\n%Order.ShippingStateProvince% %Order.ShippingCountry%\n<br />\n<br />\nShipping Method: %Order.ShippingMethod%\n<br />\n<br />\n endif% Delivered Products:\n<br />\n<br />\n%Shipment.Product(s)%\n</p>\n',1,NULL,0,0,0,0),(26,'OrderPlaced.CustomerNotification',NULL,'Order receipt from %Store.Name%.',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\nHello %Order.CustomerFullName%,\n<br />\nThanks for buying from <a href=\"%Store.URL%\">%Store.Name%</a>. Below is the summary of the order.\n<br />\n<br />\nOrder Number: %Order.OrderNumber%\n<br />\nOrder Details: <a target=\"_blank\" href=\"%Order.OrderURLForCustomer%\">%Order.OrderURLForCustomer%</a>\n<br />\nDate Ordered: %Order.CreatedOn%\n<br />\n<br />\n<br />\n<br />\nBilling Address\n<br />\n%Order.BillingFirstName% %Order.BillingLastName%\n<br />\n%Order.BillingAddress1%\n<br />\n%Order.BillingAddress2%\n<br />\n%Order.BillingCity% %Order.BillingZipPostalCode%\n<br />\n%Order.BillingStateProvince% %Order.BillingCountry%\n<br />\n<br />\n<br />\n<br />\n%if (%Order.Shippable%) Shipping Address\n<br />\n%Order.ShippingFirstName% %Order.ShippingLastName%\n<br />\n%Order.ShippingAddress1%\n<br />\n%Order.ShippingAddress2%\n<br />\n%Order.ShippingCity% %Order.ShippingZipPostalCode%\n<br />\n%Order.ShippingStateProvince% %Order.ShippingCountry%\n<br />\n<br />\nShipping Method: %Order.ShippingMethod%\n<br />\n<br />\n endif% %Order.Product(s)%\n</p>\n',1,NULL,0,0,0,0),(27,'OrderPlaced.StoreOwnerNotification',NULL,'%Store.Name%. Purchase Receipt for Order #%Order.OrderNumber%',1,'<p>\n<a href=\"%Store.URL%\">%Store.Name%</a>\n<br />\n<br />\n%Order.CustomerFullName% (%Order.CustomerEmail%) has just placed an order from your store. Below is the summary of the order.\n<br />\n<br />\nOrder Number: %Order.OrderNumber%\n<br />\nDate Ordered: %Order.CreatedOn%\n<br />\n<br />\n<br />\n<br />\nBilling Address\n<br />\n%Order.BillingFirstName% %Order.BillingLastName%\n<br />\n%Order.BillingAddress1%\n<br />\n%Order.BillingAddress2%\n<br />\n%Order.BillingCity% %Order.BillingZipPostalCode%\n<br />\n%Order.BillingStateProvince% %Order.BillingCountry%\n<br />\n<br />\n<br />\n<br />\n%if (%Order.Shippable%) Shipping Address\n<br />\n%Order.ShippingFirstName% %Order.ShippingLastName%\n<br />\n%Order.ShippingAddress1%\n<br />\n%Order.ShippingAddress2%\n<br />\n%Order.ShippingCity% %Order.ShippingZipPostalCode%\n<br />\n%Order.ShippingStateProvince% %Order.ShippingCountry%\n<br />\n<br />\nShipping Method: %Order.ShippingMethod%\n<br />\n<br />\n endif% %Order.Product(s)%\n</p>\n',1,NULL,0,0,0,0),(28,'ShipmentSent.CustomerNotification',NULL,'Your order from %Store.Name% has been %if (!%Order.IsCompletelyShipped%) partially endif%shipped.',1,'<p>\n<a href=\"%Store.URL%\"> %Store.Name%</a>\n<br />\n<br />\nHello %Order.CustomerFullName%!,\n<br />\nGood news! Your order has been %if (!%Order.IsCompletelyShipped%) partially endif%shipped.\n<br />\nOrder Number: %Order.OrderNumber%\n<br />\nOrder Details: <a href=\"%Order.OrderURLForCustomer%\" target=\"_blank\">%Order.OrderURLForCustomer%</a>\n<br />\nDate Ordered: %Order.CreatedOn%\n<br />\n<br />\n<br />\n<br />\nBilling Address\n<br />\n%Order.BillingFirstName% %Order.BillingLastName%\n<br />\n%Order.BillingAddress1%\n<br />\n%Order.BillingAddress2%\n<br />\n%Order.BillingCity% %Order.BillingZipPostalCode%\n<br />\n%Order.BillingStateProvince% %Order.BillingCountry%\n<br />\n<br />\n<br />\n<br />\n%if (%Order.Shippable%) Shipping Address\n<br />\n%Order.ShippingFirstName% %Order.ShippingLastName%\n<br />\n%Order.ShippingAddress1%\n<br />\n%Order.ShippingAddress2%\n<br />\n%Order.ShippingCity% %Order.ShippingZipPostalCode%\n<br />\n%Order.ShippingStateProvince% %Order.ShippingCountry%\n<br />\n<br />\nShipping Method: %Order.ShippingMethod%\n<br />\n<br />\n endif% Shipped Products:\n<br />\n<br />\n%Shipment.Product(s)%\n</p>\n',1,NULL,0,0,0,0),(29,'ShipmentReadyForPickup.CustomerNotification',NULL,'Your order from %Store.Name% has been %if (!%Order.IsCompletelyReadyForPickup%) partially endif%ready for pickup.',1,'<p>\n<a href=\"%Store.URL%\"> %Store.Name%</a>\n<br />\n