  `StartDateUtc` datetime(6) DEFAULT NULL,
  `EndDateUtc` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`Id`),
  KEY `IX_ED22A23331718AB1C4E03DC35EE6CE7A772786E8` (`LanguageId`),
