INSERT INTO `QueuedEmail` VALUES (1,'test@mail.com','Store name','hector.koelpin@gmail.com','Keisha Gottlieb',NULL,NULL,'',NULL,'Welcome to Your store name',1,5,'We welcome you to <a href=\"http://localhost:8080/\"> Your store name</a>.\n<br />\n<br />\nYou can now take part in the various services we have to offer you. Some of these services include:\n<br />\n<br />\nPermanent Cart - Any products added to your online cart remain there until you remove them, or check them out.\n<br />\nAddress Book - We can now deliver your products to another address other than yours! This is perfect to send birthday gifts direct to the birthday-person themselves.\n<br />\nOrder History - View your history of purchases that you have made with us.\n<br />\nProducts Reviews - Share your opinions on products with our other customers.\n<br />\n<br />\nFor help with any of our online services, please email the store-owner: <a href=\"mailto:test@mail.com\">test@mail.com</a>.\n<br />\n<br />\nNote: This email address was provided on our registration page. If you own the email and did not register on our site, please send an email to <a href=\"mailto:test@mail.com\">test@mail.com</a>.\n',NULL,NULL,0,'2026-09-20 11:46:21.635000',NULL,0,NULL),(2,'test@mail.com','Store name','hector.koelpin@gmail.com','Keisha Gottlieb',NULL,NULL,'',NULL,'Your store name. Password recovery',1,5,'<a href=\"http://localhost:8080/\">Your store name</a>\n<br />\n<br />\nTo change your password <a href=\"http://localhost:8080/passwordrecovery/confirm?token=63d05644-d8f0-4472-9f34-8ab4e1f86707&guid=532a8093-bdce-4adc-bd34-ec2bb9d1ea7f\">click here</a>.\n<br />\n<br />\nYour store name\n',NULL,NULL,0,'2026-09-20 11:49:41.500000',NULL,0,NULL),(3,'test@mail.com','Store name','hector.koelpin@gmail.com','Keisha Gottlieb',NULL,NULL,'',NULL,'Your store name. Password recovery',1,5,'<a href=\"http://localhost:8080/\">Your store name</a>\n<br />\n<br />\nTo change your password <a href=\"http://localhost:8080/passwordrecover