INSERT INTO `Topic` VALUES (1,'AboutUs',0,20,0,0,NULL,'About us','<p>Put your &quot;About Us&quot; information here. You can edit this in the admin site.</p>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(2,'CheckoutAsGuestOrRegister',0,1,0,0,NULL,'','<p><strong>Register and save time!</strong><br />Register with us for future convenience:</p><ul><li>Fast and easy check out</li><li>Easy access to your order history and status</li></ul>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(3,'ConditionsOfUse',0,15,0,0,NULL,'Conditions of Use','<p>Put your conditions of use information here. You can edit this in the admin site.</p>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(4,'ContactUs',0,1,0,0,NULL,'','<p>Put your contact information here. You can edit this in the admin site.</p>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(5,'ForumWelcomeMessage',0,1,0,0,NULL,'Forums','<p>Put your welcome message here. You can edit this in the admin site.</p>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(6,'HomepageText',0,1,0,0,NULL,'Welcome to our store','<p>Online shopping is the process consumers go through to purchase products or services over the Internet. You can edit this in the admin site.</p><p>If you have questions, see the <a href=\"http://docs.nopcommerce.com/\">Documentation</a>, or post in the <a href=\"https://www.nopcommerce.com/boards/\">Forums</a> at <a href=\"https://www.nopcommerce.com\">nopCommerce.com</a></p>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(7,'LoginRegistrationInfo',0,1,0,0,NULL,'About login / registration','<p>Put your login / registration information here. You can edit this in the admin site.</p>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(8,'PrivacyInfo',0,10,0,0,NULL,'Privacy notice','<p>Put your privacy policy information here. You can edit this in the admin site.</p>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(9,'PageNotFound',0,1,0,0,NULL,'','<p><strong>The page you requested was not found, and we have a fine guess why.</strong></p><ul><li>If you typed the URL directly, please make sure the spelling is correct.</li><li>The page no longer exists. In this case, we profusely apologize for the inconvenience and for any damage this may cause.</li></ul>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(10,'ShippingInfo',0,5,0,0,NULL,'Shipping & returns','<p>Put your shipping &amp; returns information here. You can edit this in the admin site.</p>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(11,'ApplyVendor',0,1,0,0,NULL,'','<p>Put your apply vendor instructions here. You can edit this in the admin site.</p>',1,1,NULL,NULL,NULL,0,0,NULL,NULL),(12,'VendorTermsOfService',0,1,0,0,NULL,'Terms of services for vendors','<p>Put your terms of service information here. You can edit this in the admin site.</p>',1,1,NULL,NULL,NULL,0,0,NULL,NULL);
/*!40000 ALTER TABLE `Topic` ENABLE KEYS */;
